	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode error body: %v", err)
	}
	msg := strings.ToLower(body["error"]["message"])
	if msg == "" {
		t.Fatalf("error.message is empty (body %s)", recorder.Body.String())
