+	// objects are invalid input rather than coerced or dropped.
+	var members map[string]any
+	if err := json.Unmarshal(blob, &members); err != nil {
 		return nil, false
 	}
-	if params == nil {
+	if members == nil {
 		return nil, false
 	}
+	params := make(map[string]string, len(members))
+	for key, value := range members {
+		str, ok := value.(string)
+		if !ok {
+			return nil, false
+		}
+		params[key] = str
+	}
 	return params, true
 }

